import { type ModulePanelDefinitionV1, ModulePanelDefinitionV1Schema } from './dictionary.js';
import { MODULE_PANEL_SOURCES } from './panels.generated.js';

/**
 * WI-OI-120bs (SPEED S2b): the panel components modules register in `spec.ui.panels`, generated by
 * `pnpm modules:catalog`. The dictionary compiler checks every panel placement against this catalogue; the parse here
 * catches a manifest the generator let through.
 */
let parsed: readonly ModulePanelDefinitionV1[] | undefined;

export function modulePanelCatalogue(): readonly ModulePanelDefinitionV1[] {
  parsed ??= Object.freeze(MODULE_PANEL_SOURCES.map((source) => ModulePanelDefinitionV1Schema.parse(source)));
  return parsed;
}
